import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, Color, Vector2 } from 'three/webgpu';
import { uv, mix, color, float, mul, add, noise, positionWorld } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group: CGroup } = ctx.THREE;
  const root = new CGroup();

  // ---------- Backdrop Plane with Gradient + Grain ----------
  const backdropGeom = new PlaneGeometry(7, 5.5);
  const uvNode = uv();

  const topColor = color('#0b0b10');
  const bottomColor = color('#14141a');
  const gradient = mix(topColor, bottomColor, uvNode.y);

  // Simple grain using noise
  const grain = mul(noise(uvNode.mul(float(100))), float(0.015));
  const finalColor = add(gradient, grain);

  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = finalColor;

  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, 0);
  root.add(backdrop);

  // ---------- Text Items ----------
  const textItems = [
    // kicker
    {
      content: 'NOVA ATELIER / JOURNAL',
      role: 'kicker',
      y: 1.7,
      spec: config.typography?.kicker,
      color: '#e8ecf2',
      letterSpacingEm: 0.12,
      uppercase: true,
    },
    // hero line 1
    {
      content: 'PRECISION IS',
      role: 'hero',
      y: 0.9,
      spec: config.typography?.hero,
      color: '#e8ecf2',
      letterSpacingEm: -0.015,
    },
    // hero line 2
    {
      content: 'A HABIT.',
      role: 'hero',
      y: 0.25,
      spec: config.typography?.hero,
      color: '#e8ecf2',
      letterSpacingEm: -0.015,
    },
    // body
    {
      content: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
      role: 'body',
      y: -0.8,
      spec: config.typography?.body,
      color: '#e8ecf2',
      letterSpacingEm: 0,
      maxWidth: 4.5,
    },
    // caption
    {
      content: 'ISSUE 12 / JULY 2026',
      role: 'caption',
      y: -1.9,
      spec: config.typography?.caption,
      color: '#e8ecf2',
      letterSpacingEm: 0.08,
    },
  ];

  const blocks = [];

  textItems.forEach((item) => {
    const fontSize = item.spec?.fontSize ?? 24;
    const letterSpacingPx = fontSize * (item.letterSpacingEm ?? 0);
    const txtOpts = {
      fontSize,
      color: item.color,
      align: 'left',
      letterSpacingPx,
    };
    if (item.maxWidth) txtOpts.maxWidthPx = item.maxWidth * 100; // rough conversion
    const textObj = ctx.fontAtlas.createText(item.content, txtOpts);
    textObj.position.set(-3.1, item.y, 0);
    if (item.uppercase) {
      textObj.traverse((c) => {
        if (c.isMesh && c.material && c.material.map && c.material.map.userData && c.material.map.userData.text) {
          c.material.map.userData.text = c.material.map.userData.text.toUpperCase();
        }
      });
    }
    textObj.visible = false; // initial hidden for animation
    root.add(textObj);
    blocks.push(textObj);

    // Hero shadow duplicate (only for hero lines)
    if (item.role === 'hero') {
      const shadowOpts = {
        ...txtOpts,
        color: '#16161d',
      };
      const shadowObj = ctx.fontAtlas.createText(item.content, shadowOpts);
      shadowObj.position.set(-3.1, item.y, -0.02);
      shadowObj.visible = false;
      root.add(shadowObj);
      blocks.push(shadowObj);
    }
  });

  // ---------- Accent Underline Rule ----------
  const underlineGeom = new PlaneGeometry(2.2, 0.05);
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.emissiveNode = color('#ff2a38');
  underlineMat.emissiveIntensity = 1.2;
  const underline = new Mesh(underlineGeom, underlineMat);
  underline.position.set(0, -0.15, 0.01);
  underline.scale.set(0, 1, 1); // start collapsed
  root.add(underline);

  // ---------- Animations ----------
  const timeline = gsap.timeline();

  // Rise-in stagger for each block (excluding underline)
  blocks.forEach((obj, idx) => {
    const startY = obj.position.y + 0.4;
    const originalY = obj.position.y;
    obj.position.y = startY;
    timeline.fromTo(
      obj.position,
      { y: startY },
      {
        y: originalY,
        duration: 0.7,
        ease: 'cubic-bezier(0.215,0.61,0.355,1)',
        onStart: () => {
          obj.visible = true;
        },
      },
      idx * 0.08
    );
  });

  // Underline rule scale animation after hero lands (hero lines are blocks[1] and blocks[2])
  const heroLandTime = 0.7 + 0.08 * 2; // after second hero line animation starts
  timeline.to(
    underline.scale,
    {
      x: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    heroLandTime
  );

  // Store references for cleanup
  root.userData._gsapTimeline = timeline;
  root.userData._resources = [backdropGeom, backdropMat, underlineGeom, underlineMat];

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    timeline.kill();
    const res = root.userData._resources || [];
    res.forEach((r) => {
      if (r.dispose) r.dispose();
    });
    // dispose any additional geometries/materials from text objects if needed
    blocks.forEach((obj) => {
      if (obj.traverse) {
        obj.traverse((c) => {
          if (c.isMesh) {
            if (c.geometry && c.geometry.dispose) c.geometry.dispose();
            if (c.material && c.material.dispose) c.material.dispose();
          }
        });
      }
    });
  };

  // ---------- Handlers placeholder ----------
  root.userData.handlers = {};

  return root;
}
